def _on_line_input(self, var, line_start, line_end):
    if not self.is_running or self.is_paused:
        return
    if self.mode == "chinese":
        return chinese_entry_var
    new_val = var.get()
    if len(new_val) > 0:
        last_char = new_val[-1]
        expected_char = self.current_text[self.current_index] if self.current_index < line_end else ""
        if last_char == expected_char:
            self.correct_keystrokes += 1
        else:
            self.wrong_chars.add(self.current_index)
        self.current_index += 1
        self.total_keystrokes += 1
        self._update_display()
        self._update_stats()
        if self.current_index >= len(self.current_text):
            self._finish_practice()

def _on_line_key(self, event, var, line_start, line_end):
    """Entry 按键处理，处理 Backspace"""
    if not self.is_running or self.is_paused:
        return "break"
    if self.mode == "chinese":
        return "break"
    if event.keysym == "BackSpace":
        if self.current_index > line_start:
            self.current_index -= 1
            self.wrong_chars.discard(self.current_index)
            self.total_keystrokes = max(0, self.total_keystrokes - 1)
            self._update_display()
            self._update_stats()
        return "break"
    # 阻止方向键等导航
    if event.keysym in ("Left", "Right", "Up", "Down", "Home", "End", "Tab"):
        return "break"
